 checks=[check('field variance',coeff.dot(coeff),2),check('first gradient variance',cx.dot(cx),1),check('second gradient variance',cy.dot(cy),k*k),check('field-first derivative covariance',coeff.dot(cx)),check('field-second derivative covariance',coeff.dot(cy)),check('gradient covariance',cx.dot(cy)),check('exact Gaussian radial expectation',s.integrate(r*r*s.exp(-r*r/2),(r,0,s.oo)),s.sqrt(s.pi/2)),check('elliptic angular reduction',s.cos(theta)**2+k*k*s.sin(theta)**2,k*k*(1-p*s.cos(theta)**2)),check('complete coarea normalization',4*s.pi*s.pi/(2*s.sqrt(s.pi))*s.sqrt(s.pi/2)*(2*k/s.pi)*s.elliptic_e(p),a),truth('strict elliptic parameter domain',bool(0<p<1))]
 pool=[(a/s.sqrt(2),'assign variance four instead of two to the field density'),(a*s.sqrt(2),'assign variance one instead of two to the field density'),(a/k,'omit the frequency factor in the anisotropic gradient norm'),(a*k,'count the already integrated vertical periods a second time'),(a/(2*s.pi),'integrate only one coordinate period in the square area'),(2*s.sqrt(2)*s.pi*k*s.elliptic_e(p*p),'treat the elliptic parameter as a modulus and square it')]
 return item(Q,a,pool,steps,checks,['Length is ordinary Euclidean one-dimensional measure. All Gaussian coefficients have variance one. The integer vertical frequency ranges from two through eleven. E is defined using its parameter, not its square root.'],['Almost surely both sinusoidal amplitudes are positive and unequal, so zero is a regular value on the periodic torus. For any regular level, the coarea formula for coordinate projections bounds total absolute horizontal variation by 4*pi*k and total absolute vertical variation by 4*pi; arclength is at most their sum. The bound is uniform in the level and coefficients. The band coarea average consequently converges to the zero-level length and is bounded by the same constant; the finite set of critical values has Lebesgue measure zero in the level parameter. Expectation and the limit can be interchanged by dominated convergence. At a fixed point all coefficient combinations are jointly Gaussian and have the explicitly checked diagonal covariance, hence are independent. Tonelli separates the spatial integral and expectation. Polar coordinates for two independent unit normals have independent uniform angle and Rayleigh radius with the checked mean. The angular integral reduces to the defined complete elliptic integral after a quarter-period shift. No external random-field formula is taken on trust.'],'stationary-Gaussian-two-frequency-nodal-length')

